SQL
docker compose exec -T database pg_dump -U january -Fc january > "$dump"
docker compose exec -T database createdb -U january "$restore_db"
docker compose exec -T database pg_restore -U january -d "$restore_db" < "$dump"
result="$(docker compose exec -T database psql -At -U january -d "$restore_db" -c "SELECT (SELECT version_num FROM alembic_version), (SELECT count(*) FROM messages WHERE id='60000000-0000-0000-0000-000000000001' AND text IS NULL AND content_redacted_at IS NOT NULL), (SELECT count(*) FROM outbound_actions WHERE id='a0000000-0000-0000-0000-000000000001' AND status='delivered' AND idempotency_key='synthetic-backup-idempotency'), (SELECT count(*) FROM safety_policy_decisions), (SELECT count(*) FROM rate_limit_events), (SELECT count(*) FROM operational_recovery_items WHERE disposition='dead_letter'), (SELECT count(*) FROM operational_recovery_items WHERE disposition='quarantine'), (SELECT count(*) FROM generated_voice_artifacts a JOIN telegram_voice_generation_jobs j ON j.id=a.generation_job_id JOIN outbound_actions o ON o.generated_voice_artifact_id=a.id WHERE a.id='e2000000-0000-0000-0000-000000000001' AND a.status='ready' AND a.format='ogg_opus' AND a.mime_type='audio/ogg' AND a.byte_size=5 AND octet_length(a.audio_bytes)=5 AND encode(a.audio_bytes,'hex')='4f67675300' AND j.status='completed' AND o.kind='voice' AND o.status='pending'), (SELECT count(*) FROM conversation_feedback f JOIN conversation_feedback_events e ON e.feedback_id=f.id WHERE f.id='f0000000-0000-0000-0000-000000000001' AND f.value='helpful' AND f.revision=1 AND e.value='helpful' AND e.revision=1)")"
[[ "$result" == "0026_conversation_feedback|1|1|1|1|1|1|1|1" ]]
echo "Synthetic PostgreSQL backup/restore rehearsal: valid (revision, redaction, idempotency, safety/rate, recovery, live voice artifact, feedback state/history)"
